Catalogue & Search Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Catalogue & Search Container", "Catalogue & Search Container") {
    Component(Search Controller, "Search Controller", "Java/Spring Boot", "Handles incoming HTTP/gRPC search requests and routes them to the search service.")
    Component(Search Service, "Search Service", "Java/Spring Boot", "Implements business logic for cataloguing, searching, and telemetry event publishing.")
    Component(Index Repository, "Index Repository", "Java/Spring Boot", "Interacts with Elasticsearch to query the search index and execute upserts.")
    Component(Cataloguing Event Consumer, "Cataloguing Event Consumer", "Java/Spring Boot", "Consumes item mutation events from RabbitMQ to update the search index.")
}

Rel(Search Controller, Search Service, "Delegates search requests", "Method Call")
Rel(Search Service, Index Repository, "Executes queries and upserts", "Java Method")
Rel(Cataloguing Event Consumer, Index Repository, "Triggers index updates upon receiving mutation events", "Java Method")

@enduml

RabbitMQ Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the RabbitMQ Message Broker container

Container_Boundary("RabbitMQ Message Broker", "RabbitMQ Message Broker") {
    Component(Notification_Exchange, "Notification Exchange", "RabbitMQ Exchange", "Routes published async events to the notification queue.")
    Component(DLX_Exchange, "DLX Exchange", "RabbitMQ Dead Letter Exchange", "Handles routing of dead-lettered messages for later inspection and replay.")
    Component(Notification_Queue, "Notification Queue", "RabbitMQ Quorum Queue", "Stores critical notifications reliably for consumption by workers.")
    Component(Dead_Letter_Queue, "Dead Letter Queue", "RabbitMQ Quorum Queue", "Holds failed or unprocessable messages for administrative review.")
}

Rel(Notification_Exchange, Notification_Queue, "Routes messages", "AMQP")
Rel(Dead_Letter_Queue, Notification_Exchange, "Republishes messages for retry", "AMQP")

@enduml
